p_chk_c:		; call chk (normal)
			pop hl			; got
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_got), de
			pop hl			; want
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_want), de
			ld (p_chk_rs), sp
			ld sp, p_chk
			jp ntc_xn
p_chk_r:		; end of chk
			ld sp, (p_chk_rs)
			jp ntc_xn
p_chks_c:		; call chks (normal)
			pop hl			; got
			ld de, var_chks_got
			ld b, 255
p_chks_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_chks_si0_e
			inc hl
			inc de
			djnz p_chks_si0
			xor a
			ld (de), a
p_chks_si0_e:
			pop hl			; want
			ld de, var_chks_want
			ld b, 255
p_chks_si1:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_chks_si1_e
			inc hl
			inc de
			djnz p_chks_si1
			xor a
			ld (de), a
p_chks_si1_e:
			ld (p_chks_rs), sp
			ld sp, p_chks
			jp ntc_xn
p_chks_r:		; end of chks
			ld sp, (p_chks_rs)
			jp ntc_xn
p_sumof_c:		; call sumof (normal)
			pop hl			; v() descriptor
			ld de, pa_sumof_v
			ld bc, 12
			ldir
			ld hl, 0
