			ldir
			ld (p_fresh_rs), sp
			ld sp, p_fresh
			jp ntc_xn
p_fresh_r:		; end of fresh
			ld sp, (p_fresh_rs)
			jp ntc_xn
p_kept_c:		; call kept (normal)
			ld hl, 0
			ld (var_kept_kept), hl
			ld (p_kept_rs), sp
			ld sp, p_kept
			jp ntc_xn
p_kept_r:		; end of kept
			ld sp, (p_kept_rs)
			jp ntc_xn
p_totalx_c:		; call totalx (normal)
			pop hl			; a().x descriptor
			ld de, pa_totalx_a_x
			ld bc, 12
			ldir
			pop hl			; a().name descriptor
			ld de, pa_totalx_a_name
			ld bc, 12
			ldir
			ld hl, 0
			ld (var_totalx_totalx), hl
			ld hl, 0
			ld (var_totalx_k), hl
			ld (p_totalx_rs), sp
			ld sp, p_totalx
			jp ntc_xn
p_totalx_r:		; end of totalx
			ld sp, (p_totalx_rs)
			jp ntc_xn
p_names_c:		; call names (normal)
			pop hl			; a().x descriptor
			ld de, pa_names_a_x
			ld bc, 12
			ldir
			pop hl			; a().name descriptor
			ld de, pa_names_a_name
			ld bc, 12
			ldir
			xor a
			ld (var_names_names), a
			ld (p_names_rs), sp
			ld sp, p_names
			jp ntc_xn
p_names_r:		; end of names
			ld sp, (p_names_rs)
			jp ntc_xn
p_bumpx_c:		; call bumpx (normal)
			pop hl			; a().x descriptor
			ld de, pa_bumpx_a_x
			ld bc, 12
			ldir
			pop hl			; a().name descriptor
			ld de, pa_bumpx_a_name
			ld bc, 12
			ldir
			ld (p_bumpx_rs), sp
			ld sp, p_bumpx
			jp ntc_xn
p_bumpx_r:		; end of bumpx
			ld sp, (p_bumpx_rs)
			jp ntc_xn
p_bag_item_get_c:		; call item (normal)
			pop hl			; i
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_bag_item_get_i), de
			ld hl, 0
			ld (var_bag_item_get_item), hl
			ld (p_bag_item_get_rs), sp
			ld sp, p_bag_item_get
			jp ntc_xn
p_bag_item_get_r:		; end of item
			ld sp, (p_bag_item_get_rs)
			jp ntc_xn
p_bag_item_let_c:		; call item (normal)
			pop hl			; i
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_bag_item_let_i), de
			pop hl			; v
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_bag_item_let_v), de
			ld (p_bag_item_let_rs), sp
			ld sp, p_bag_item_let
			jp ntc_xn
p_bag_item_let_r:		; end of item
			ld sp, (p_bag_item_let_rs)
			jp ntc_xn

